import clsx from 'clsx';
import React, { ReactNode, forwardRef } from 'react';

import { chipContentCSS, chipPrefixCSS } from './ChipContent.sty.js';
import { _useChipContext } from './contexts/useChipContext.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

//#region Typings
/** Accepted properties for the Content */
export interface ChipContentProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the prefix or suffix slot. */
  children: ReactNode;
}
//#endregion

/** ChipContent component, used for adding elements to the prefix/suffix slot. */
export const ChipContent = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  ChipContentProps & { $isPrefixWithKey?: boolean }
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    $isPrefixWithKey,
    ...remainingProps
  } = props;
  const { size } = _useChipContext();

  return (
    <div
      ref={forwardedRef}
      className={clsx(
        chipContentCSS({
          size,
        }),
        consumerClassName,
      )}
      style={consumerStyle}
      data-testid={dataTestId}
      {...remainingProps}
    >
      {children}
    </div>
  );
});

/** Component used for adding elements to the prefix slot. */
export const ChipPrefix = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  ChipContentProps
>((props, forwardedRef) => {
  const {
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...restProps
  }: ChipContentProps = props;
  const { hasKey } = _useChipContext();

  return (
    <ChipContent
      data-testid={dataTestId}
      ref={forwardedRef}
      className={clsx(
        {
          [chipPrefixCSS]: hasKey,
        },
        consumerClassName,
      )}
      style={consumerStyle}
      $isPrefixWithKey={hasKey}
      {...restProps}
    />
  );
});

/** Component used for adding elements to the suffix slot. */
export const ChipSuffix = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  ChipContentProps
>((props, forwardedRef) => {
  const {
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...restProps
  }: ChipContentProps = props;

  return (
    <ChipContent
      data-testid={dataTestId}
      ref={forwardedRef}
      className={consumerClassName}
      style={consumerStyle}
      {...restProps}
    />
  );
});

(ChipPrefix as typeof ChipPrefix & { displayName: string }).displayName =
  'Chip.Prefix';
(ChipSuffix as typeof ChipSuffix & { displayName: string }).displayName =
  'Chip.Suffix';
